    const VIEW_KEY = 'tda.wx.view', seasonView = () => { const m = NWSX.ct(Date.now()).mo; return m >= 10 || m <= 3 ? 'heat' : 'cool'; }, seasonKey = () => { const c = NWSX.ct(Date.now()); return seasonView() + (c.mo <= 3 ? c.y - 1 : c.y); }, heatV = () => st.view === 'heat';
    { const v = store.get(VIEW_KEY, null); st.view = v && v.season === seasonKey() && (v.view === 'heat' || v.view === 'cool') ? v.view : seasonView(); st.line = heatV() ? 'heat' : 'repair'; }
    const dowY = ymd => NWSX.DOW[new Date(ymd + 'T12:00:00Z').getUTCDay()], nextY = ymd => new Date(Date.parse(ymd + 'T12:00:00Z') + 864e5).toISOString().slice(0, 10), shortDate = ymd => `${SLM.MONTHS[+String(ymd).slice(5, 7) - 1]} ${+String(ymd).slice(8, 10)}`, below = (a, b) => isN(a) && isN(b) && Math.round(a) < Math.round(b);
    /* The wider picture, when the live layer holds it: the cold forecast across the 12 counties and the season record. Both are optional. */
    const wide = () => { try { const L = window.TDA_LIVE; if (!L || !L.derive || !L.derive.cold || typeof LIVE === 'undefined') return null; const c = L.derive.cold(LIVE.all(), new Date()); return c && c.ok && !c.stale && isN(c.minLow) && c.worst ? c : null; } catch (e) { return null; } };
